/**
 * Provides the single-tier (no shared artifact store) protocol.
 *
 * @since 0.1.0
 * @category layers
 */
export const layerLocal = Layer.succeed(ArtifactSync)(makeLocal());
/**
 * Builds the two-tier protocol over a local and a shared artifact store.
 *
 * @since 0.1.0
 * @category constructors
 */
export const make = (options) => {
    const { local, remote } = options;
    const downloadPolicy = options.downloadPolicy ?? RemoteArtifacts.downloadPolicyOf(remote) ?? "all";
    const publicationFailed = (digests, message, cause) => new ArtifactPublicationFailed({ code: "artifact_publication_failed", digests, message, cause });
    return {
        publish: (digests) => Effect_1.suspend({ publish: () => { return withSpan(Effect_1.gen(runtime.$iteratorFrame(runtime.$joinedFrame(function* () {
                if (digests.length === 0)
                    return;
                const missing = yield* $catchExpression(() => remote.findMissing(digests), (cause) => Effect_1.suspend(() => { return Effect_1.fail(publicationFailed(digests, "the shared tier refused a probe", cause)); }));
                {
                    let pending_1 = runtime.$normal;
                    try {
                        for (const digest of missing) {
                            try {
                                {
                                    const bytes = yield* (Effect.mapError(local.get(digest), (cause) => 
                                    // The blob is referenced by evidence this host just produced, so
                                    // it should be in this host's own store. If it is not, the
                                    // evidence is not publishable — and saying so is far better than
                                    // publishing an entry nobody can replay.
