                // upload but did not durably store it is exactly the state that makes a
                // published entry unreplayable, and it is cheap to rule out — one
                // batched round trip over the set we just wrote.
                const stillMissing = yield* $catchExpression(() => remote.findMissing(missing), (cause) => Effect_1.suspend(() => { return Effect_1.fail(publicationFailed(missing, "the shared tier refused a probe", cause)); }));
