            }))), "ArtifactSync.publish"); } }.publish),
        hydrate: (digests) => Effect_1.suspend({ hydrate: () => { return withSpan(Effect_1.gen(runtime.$iteratorFrame(runtime.$joinedFrame(function* () {
                // Every refusal below falls back to re-executing the step, which is
                // correct and silent. The warning is the operator's only signal that a
                // tier stopped serving replays.
                const fallBack = (message, digests) => (cause) => { var topic_1; return (topic_1 = Effect.logWarning(`artifact hydration falls back to re-execution: ${message}: ${digests.join(", ")}`), Effect.annotateLogs({ reason: cause.message })(topic_1)); };
                const missing = yield* (Effect.option(Effect.tapError(local.findMissing(digests), fallBack("the local tier refused a probe", digests))));
                if (missing._tag === "None")
                    return false;
                if (downloadPolicy !== "all") {
                    if (missing.value.length === 0)
                        return true;
                    // One batched probe, no body transfer: the answer these policies owe
                    // the caller is "can this replay be satisfied", and `findMissing`
                    // answers exactly that. A tier that refuses the probe is
                    // indistinguishable from one that holds nothing, so the replay is
                    // refused either way.
                    const elsewhere = yield* (Effect.option(Effect.tapError(remote.findMissing(missing.value), fallBack("the shared tier refused a probe", missing.value))));
                    return elsewhere._tag === "Some" && elsewhere.value.length === 0;
                }
                {
                    let pending_2 = runtime.$normal;
                    try {
                        for (const digest of missing.value) {
                            try {
                                {
                                    // Read-through, one artifact at a time and only on demand: the remote
                                    // read is digest-verified by `RemoteArtifacts`, and the local `put`
                                    // re-addresses the bytes, so a tier serving wrong content cannot get
                                    // them written into this workspace.
                                    const written = yield* (Effect.option(Effect.tapError(Effect.flatMap(Effect.flatMap(remote.get(digest), (bytes) => local.put(bytes))
                                    // A custom tier may skip that verification; the address `put`
                                    // returned is the proof the requested blob is now local.
                                    , (address) => address === digest ?
                                        Effect.void :
                                        Effect.fail({ message: `the shared tier served the bytes of ${address}` })), fallBack("the artifact could not be fetched", [digest]))));
                                    if (written._tag === "None")
                                        return false;
                                }
                            }
                            catch (thrown_3) {
                                pending_2 = thrown_3;
                                break;
                            }
                        }
                    }
                    catch (thrown_4) {
                        throw runtime.$finallyFailure(pending_2, thrown_4);
                    }
                    if (pending_2 !== runtime.$normal)
                        throw pending_2;
                }
                return true;
            }))), "ArtifactSync.hydrate"); } }.hydrate)
    };
};
/**
 * Provides the two-tier protocol, taking the local store from the
 * `ArtifactStore` tag and the shared store from the supplied effect.
 *
 * The two tiers cannot both be layers: they inhabit the same tag, so composing
 * them would shadow one with the other.
 *
 * @since 0.1.0
 * @category layers
 */
export const layer = (remote, options) => Layer.effect(ArtifactSync)(Effect_1.gen(runtime.$joinedFrame(function* () {
    const local = yield* ArtifactStore.ArtifactStore;
    const shared = yield* remote;
    return make({
        local,
        remote: shared,
        ...(options?.downloadPolicy === undefined ? {} : { downloadPolicy: options.downloadPolicy })
    });
})));

/**
 * The envelope a durable run's state is persisted inside.
 *
 * The engine never stores a flow's payload bare — it wraps it in a versioned
 * struct, so a store row written by an older build decodes under a known
 * shape instead of being guessed at. `version` is a literal rather than a
 * number for exactly that reason: a future revision adds a new literal and
 * both remain decodable.
 *
 * Time travel reads these rows too, deriving the state AT a frame by
 * replaying run-decision records rather than trusting the row's latest value.
 *
 * @since 0.1.0
 */
import { CapabilityPattern } from "@smthrs/capability/Capability";
import { Flow } from "@smthrs/flow";
import * as Schema from "effect/Schema";
/** @private */
const PositiveSafeInt = Schema.Int.check(Schema.isGreaterThanOrEqualTo(1));
/**
 * What a linked child does when the run that spawned it ends.
 *
 * `cancel` is the default and the shape a `.child()` boundary takes: the
 * parent is waiting on this child, so a parent that stops waiting — because it
 * completed, failed, or was cancelled — leaves nothing behind. `detach` is the
 * shape a fire-and-forget spawn takes: the parent deliberately did not wait,
 * so the child outlives it and keeps its own claim and its own journal.
 *
 * The policy is recorded on the CHILD rather than on the edge because it is a
 * property of how the child was started, and because a child with two parents
 * (the diamond `flows_run_parents` permits) must answer the question once.
 *
 * @since 0.1.0
 * @category schemas
 */
export const OnParentExit = Schema.Literals(["cancel", "detach"]);
/**
 * The versioned state stored for a durable flow run: which flow it is, the
 * encoded `payload` it was started with, and — as they arrive — its
 * `result` and its cancellation timestamp.
 *
 * `parentExecutionId` is present only on a child run, and is what makes a
 * spawned subflow reachable from the run that spawned it. `onParentExit`
 * travels with it: it is what the parent's terminal transition reads to decide
 * whether this child ends with it.
 *
 * @since 0.1.0
 * @category schemas
 */
export const RunState = Schema.Struct({
    version: Schema.Literal(1),
    flowName: Schema.NonEmptyString,
    payload: Schema.Unknown,
    capabilityCeilings: Schema.optionalKey(Schema.Array(Schema.Array(CapabilityPattern))),
    // Key origins are immutable fork metadata, independent of the chosen frame.
    // Copied attempts, not ancestry alone, authorize reuse of an origin's key.
    forkKeyRunIds: Schema.optionalKey(Schema.Array(Schema.NonEmptyString)),
    // A retry from a step (`FlowRuntime.retryFrom`): the settled run it
    // replays, the node it runs from (absent on a carried child, which replays
    // whole), and the source's `.child()` boundary nodes that settled before
    // that node. Opening one of those boundaries again carries the child the
    // source opened there. Immutable from admission, like `forkKeyRunIds`.
    retryFrom: Schema.optionalKey(Schema.Struct({
        source: Schema.NonEmptyString,
        step: Schema.optionalKey(Schema.NonEmptyString),
        boundaries: Schema.Array(Schema.NonEmptyString),
    })),
    parentExecutionId: Schema.optionalKey(Schema.NonEmptyString),
    onParentExit: Schema.optionalKey(OnParentExit),
    maxRounds: Schema.optionalKey(PositiveSafeInt),
    // The lineage deadline a round after a handoff runs under, copied from the
    // `Flow.Handoff` that opened it.
    deadline: Schema.optionalKey(Flow.LineageDeadline),
    result: Schema.optionalKey(Schema.Unknown),
    // `run` is the cancellation run its flow declared (`Flow.OnCancel`), admitted with the cancellation.
    cancellation: Schema.optionalKey(Schema.Struct({
        interruptedAtMs: Schema.Number.check(Schema.isGreaterThanOrEqualTo(0)),
        run: Schema.optionalKey(Schema.NonEmptyString)
    })),
    // Who started the run and when it was admitted, as its usage metrics label
    // it (`@smthrs/flow` `RunMetrics`): the door and the actor kind, never who.
    // Every round of a lineage carries its first round's, so the lineage's
    // settlement measures from the first admission. Absent on a run admitted
    // before the field existed.
    origin: Schema.optionalKey(Schema.Struct({
        door: Schema.String,
        actor: Schema.String,
        admittedAtMs: Schema.Number.check(Schema.isGreaterThanOrEqualTo(0)),
    })),
    // When the run parked on its current durable wait, and on what, so the
    // resume that ends the wait measures it even in another process.
    parked: Schema.optionalKey(Schema.Struct({
        atMs: Schema.Number.check(Schema.isGreaterThanOrEqualTo(0)),
        kind: Schema.String,
    })),
});
/**
 * Why a driver released a run it still owned, recorded on its
 * `interrupt-released` run decision.
 *
