/** Builds the tag-keyed record of attributed counter views for one operation. */
const byOutcome = (metric, attributes, tags) => Object.fromEntries(tags.map((tag) => [tag, Metric.withAttributes(metric, { ...attributes, outcome: attributeValue(tag) })]));
